const readline = require('fs');

const data = readline.readFileSync('/dev/stdin', 'utf8')
  .split(/\s+/)
  .filter(s => s.length > 0)
  .map(Number);

const n = data[0];
let dario = 0, xerxes = 0;

// A figura corresponde ao Pedra-Papel-Tesoura-Lagarto-Spock:
// a mão A vence a mão B se (B - A) mod 5 é 1 ou 2,
// ou seja, cada mão vence as duas mãos seguintes no ciclo 0..4.
for (let i = 0; i < n; i++) {
  const d = data[1 + 2 * i];
  const x = data[2 + 2 * i];
  const diff = ((x - d) % 5 + 5) % 5;
  if (diff === 1 || diff === 2) dario++;
  else xerxes++;
}

console.log(dario > xerxes ? "dario" : "xerxes");
